// events/advancedConfig.js

const JSZip = require('jszip');
const fs = require('fs');
const path = require('path');
const Discord = require("discord.js");
const { JsonDatabase } = require("wio.db");
const axios = require("axios");

const { Product } = require("../database/models/Models");

const db = new JsonDatabase({ databasePath: "./jsons/produtos.json" });

const msg = {};


module.exports = async (interaction) => {
    // Manipulador para Configurações Avançadas
    if (interaction.isStringSelectMenu() && interaction.customId === "advanced_config_select") {
        const options = interaction.values[0];
        if (options === "create_sale") {
            msg[interaction.message.id] = interaction.user.id;
            await interaction.update({
                components: [
                    new Discord.ActionRowBuilder().addComponents(
                        new Discord.StringSelectMenuBuilder()
                            .addOptions(
                                {
                                    label: "Criar Nova Venda",
                                    description: "Crie um novo BOT para anunciar",
                                    emoji: "<:1216187635719213067:1241812157532864684>",
                                    value: "create_bot"
                                }
                            )
                            .setCustomId("create_bot_select")
                            .setPlaceholder("Selecione qual configuração avançada deseja modificar")
                    ),
                    new Discord.ActionRowBuilder().addComponents(
                        new Discord.ButtonBuilder()
                            .setCustomId("go_back_advanced")
                            .setLabel("Voltar")
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji("<:voltarkauan:1177188031179010119>")
                    )
                ]
            });
        }
    }

    // Manipulador para Selecionar Opção "Criar Nova Venda"
    if (interaction.isStringSelectMenu() && interaction.customId === "create_bot_select") {
        const modal = new Discord.ModalBuilder()
            .setCustomId("modal_create_bot")
            .setTitle(`${interaction.user.displayName} - Nova Venda`);

        const productNameInput = new Discord.TextInputBuilder()
            .setLabel("Nome do Produto (BOT)")
            .setPlaceholder("TICKET|WHITELIST|AUTOCONNECT (EXEMPLO)")
            .setRequired(true)
            .setStyle(TextInputStyle.Short)
            .setCustomId("productName");

        const mainFileInput = new Discord.TextInputBuilder()
            .setCustomId("mainFile")
            .setStyle(TextInputStyle.Short)
            .setLabel("Arquivo Principal")
            .setPlaceholder("Exemplo: index.js / start.js / default.js")
            .setRequired(true);

        modal.addComponents(
            new Discord.ActionRowBuilder().addComponents(productNameInput),
            new Discord.ActionRowBuilder().addComponents(mainFileInput)
        );

        await interaction.showModal(modal);
    }

    // Manipulador para Submissão do Modal "Criar Bot"
    if (interaction.isModalSubmit() && interaction.customId === "modal_create_bot") {
        const productName = interaction.fields.getTextInputValue("productName").trim();
        const mainFile = interaction.fields.getTextInputValue("mainFile").trim();

        // Verifica se o produto já existe
        const existingProduct = await Product.findOne({ productName });
        if (existingProduct) {
            return interaction.reply({
                content: `⚠ | Já existe este (PRODUTO/BOT)!\n **Caso Queira configura-lo use /configpainel ${productName}**`,
                ephemeral: true
            });
        }

        // Atualiza a mensagem para solicitar o upload do arquivo ZIP
        await interaction.update({
            embeds: [
                new Discord.EmbedBuilder()
                    .setDescription(`<:1236149848680566794:1241812196162535503> ${interaction.user}, para concluir a primeira etapa de configuração do seu novo produto, solicitamos que nos envie um arquivo compactado (.ZIP) contendo seu BOT. Por favor!`)
            ],
            components: []
        });

        // Cria um coletor de mensagens para obter o arquivo ZIP
        const collector = interaction.channel.createMessageCollector({
            filter: m => m.attachments.first() && m.attachments.first().name.endsWith('.zip'),
            max: 1,
            time: 60000
        });

        collector.on('collect', async (message) => {
            if (message.author.id !== interaction.user.id) return;

            const attachment = message.attachments.first();
            const zip = new JSZip();

            try {
                // Baixa o arquivo ZIP
                const response = await axios.get(attachment.url, { responseType: 'arraybuffer' });
                const zipData = await zip.loadAsync(response.data);

                // Atualiza a mensagem para indicar que os arquivos estão sendo verificados
                await interaction.message.edit({
                    embeds: [
                        new Discord.EmbedBuilder()
                            .setTitle(`<:1248300403452280884:1248760691289096213> ${interaction.guild.name} | Configurações Avançadas <:1248300403452280884:1248760691289096213>`)
                            .setDescription(`<:1236149726009888809:1241812186469503026> Estamos verificando os arquivos enviados.`)
                    ],
                    components: []
                });

                // Remove a mensagem do usuário após processamento
                await message.delete().catch(err => console.error('Erro ao deletar mensagem do usuário:', err));

                // Verifica se o ZIP contém 'package.json' e 'squarecloud.config' ou 'squarecloud.app'
                if (zipData.files['package.json'] && (zipData.files['squarecloud.config'] || zipData.files['squarecloud.app'])) {
                    const packageJsonContent = await zipData.file('package.json').async('string');
                    const packageJson = JSON.parse(packageJsonContent);

                    // Atualiza o campo 'main' no package.json
                    packageJson.main = mainFile;
                    zipData.file('package.json', JSON.stringify(packageJson, null, 2));

                    // Atualiza o arquivo de configuração principal
                    const configFileName = zipData.files['squarecloud.config'] ? 'squarecloud.config' : 'squarecloud.app';
                    let configContent = await zipData.file(configFileName).async('string');
                    let lines = configContent.split('\n');
                    for (let i = 0; i < lines.length; i++) {
                        if (lines[i].startsWith('MAIN=')) {
                            lines[i] = 'MAIN=' + mainFile;
                        }
                    }
                    configContent = lines.join('\n');
                    zipData.file(configFileName, configContent);

                    // Gera o novo arquivo ZIP e salva na pasta 'source'
                    const outputDir = './source';
                    if (!fs.existsSync(outputDir)) {
                        fs.mkdirSync(outputDir);
                    }
                    const outputPath = path.join(outputDir, `${productName}.zip`);
                    fs.writeFileSync(outputPath, await zipData.generateAsync({ type: "nodebuffer" }));

                    // Salva os detalhes do produto no banco de dados
                    const newProduct = new Product({
                        productName,
                        preco: {
                            embed: {
                                color: "Default",
                                title: `${interaction.guild.name} | ${productName}`,
                                description: `Para realizar a compra de seu PRODUTO clique abaixo em \`🛒 Realizar Compra\``,
                                banner: null,
                                preview: "remover"
                            }
                        }
                    })
                    await newProduct.save()

                    // Atualiza a mensagem com as configurações avançadas concluídas
                    await interaction.message.edit({
                        embeds: [
                            new Discord.EmbedBuilder()
                                .setTitle(`Configurações Avançadas`)
                                .setAuthor({ name: client.user.username, iconURL: client.user.displayAvatarURL({ dynamic: true }) })
                                .setFooter({ text: interaction.guild.name, iconURL: interaction.guild.iconURL({ dynamic: true }) })
                                .setDescription(`Olá! Informamos que a aplicação de **${productName}** foi criada. Caso tenha interesse, sinta-se à vontade para prosseguir com a configuração abaixo. Utilize o comando \`/configpainel\` para alterar outras opções.`)
                        ],
                        components: [
                            new Discord.ActionRowBuilder().addComponents(
                                new Discord.ButtonBuilder()
                                    .setCustomId("go_back_advanced")
                                    .setLabel("Voltar")
                                    .setStyle(ButtonStyle.Secondary)
                                    .setEmoji("<:voltarkauan:1177188031179010119>")
                            )
                        ]
                    });

                } else {
                    // Atualiza a mensagem indicando que o arquivo ZIP está incorreto
                    await interaction.message.edit({
                        embeds: [
                            new Discord.EmbedBuilder()
                                .setTitle(`<:1248300403452280884:1248760691289096213> ${interaction.guild.name} | Configurações Avançadas <:1248300403452280884:1248760691289096213>`)
                                .setDescription(`Não conseguimos verificar os arquivos enviados. Verifique se o ZIP contém 'package.json' e 'squarecloud.config' ou 'squarecloud.app'.`)
                        ],
                        components: [
                            new Discord.ActionRowBuilder().addComponents(
                                new Discord.ButtonBuilder()
                                    .setCustomId("go_back_advanced")
                                    .setLabel("Voltar")
                                    .setStyle(ButtonStyle.Secondary)
                                    .setEmoji("<:voltarkauan:1177188031179010119>")
                            )
                        ]
                    });
                }
            } catch (error) {
                console.error(error);
                await interaction.message.edit({
                    embeds: [
                        new Discord.EmbedBuilder()
                            .setTitle(`<:1248300403452280884:1248760691289096213> ${interaction.guild.name} | Configurações Avançadas <:1248300403452280884:1248760691289096213>`)
                            .setDescription(`Ocorreu um erro ao processar o arquivo ZIP. Por favor, tente novamente.`)
                    ],
                    components: [
                        new Discord.ActionRowBuilder().addComponents(
                            new Discord.ButtonBuilder()
                                .setCustomId("go_back_advanced")
                                .setLabel("Voltar")
                                .setStyle(ButtonStyle.Secondary)
                                .setEmoji("<:voltarkauan:1177188031179010119>")
                        )
                    ]
                });
            }
        });

        collector.on('end', collected => {
            if (collected.size === 0) {
                interaction.followUp({
                    embeds: [
                        new Discord.EmbedBuilder()
                            .setDescription(`${EMOJIS.erro} | Nenhum arquivo ZIP foi recebido no tempo esperado.`)
                    ],
                    ephemeral: true
                });
            }
        });
    }

    // Manipulador para Botão "Voltar" nas Configurações Avançadas
    if (interaction.isButton() && interaction.customId === "go_back_advanced") {
        await interaction.update({
            components: [
                new Discord.ActionRowBuilder().addComponents(
                    new Discord.StringSelectMenuBuilder()
                        .addOptions(
                            {
                                label: "Criar Nova Venda",
                                description: "Crie um novo BOT para anunciar",
                                emoji: "<:1216187635719213067:1241812157532864684>",
                                value: "create_bot"
                            }
                        )
                        .setCustomId("create_bot_select")
                        .setPlaceholder("Selecione qual configuração avançada deseja modificar")
                ),
                new Discord.ActionRowBuilder().addComponents(
                    new Discord.ButtonBuilder()
                        .setCustomId("go_back_main")
                        .setLabel("Voltar")
                        .setStyle(ButtonStyle.Secondary)
                        .setEmoji("<:voltarkauan:1177188031179010119>")
                )
            ]
        });
    }

    // Manipulador para Botão "Voltar" Principal das Configurações Avançadas
    if (interaction.isButton() && interaction.customId === "go_back_main") {
        await interaction.update({
            embeds: [
                new Discord.EmbedBuilder()
                    .setTitle(`Configurações Avançadas`)
                    .setAuthor({ name: client.user.username, iconURL: client.user.displayAvatarURL({ dynamic: true }) })
                    .setFooter({ text: interaction.guild.name, iconURL: interaction.guild.iconURL({ dynamic: true }) })
